Lemma bl_C : forall (fx : FPState) regs (m : word -> option byte) (s bil : Z),
  (4096 + 48 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 48)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 48) ->
  getr regs 9 = Z_to_bv 64 bil ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 189128) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 98604) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 189136 /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 9 = Z_to_bv 64 bil /\ getr regs' 10 = Z_to_bv 64 (bil + 88) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
