Lemma bl_Lb : forall (fx : FPState) regs (m : word -> option byte) (s bil ls i lf : Z),
  (4096 + 48 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil)%Z ->
  (bil + 104 <= s - 48)%Z ->
  (4096 <= ls)%Z ->
  (ls + 80 <= 2 ^ 47)%Z ->
  (0 <= i <= 9)%Z ->
  (0 <= lf < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (bil + 96)) 8 = Some (Z_to_le_bytes 8 ls) ->
  rdn SEGS m (Z_to_bv 64 (ls + 8 * i)) 8 = Some (Z_to_le_bytes 8 lf) ->
  getr regs 2 = Z_to_bv 64 (s - 48) ->
  getr regs 9 = Z_to_bv 64 bil ->
  getr regs 18 = Z_to_bv 64 (8 * i) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 189192) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 194572) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 189208 /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 9 = Z_to_bv 64 bil /\ getr regs' 10 = Z_to_bv 64 lf /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
